+import { randomUUID } from 'node:crypto';
+import { mkdir, readFile, rename, unlink, writeFile } from 'node:fs/promises';
+import { dirname } from 'node:path';
+
+export function createBookStore(filePath) {
+  let pendingWrite = Promise.resolve();
+
+  async function list() {
+    try {
+      return JSON.parse(await readFile(filePath, 'utf8'));
+    } catch (error) {
+      if (error.code === 'ENOENT') return [];
+      throw error;
+    }
+  }
+
+  async function save(books) {
+    await mkdir(dirname(filePath), { recursive: true });
+    const temporaryPath = "'`${filePath}.${randomUUID()}.tmp`;
+
+    try {
+      await writeFile(temporaryPath, `${JSON.stringify(books, null, 2)}'"\\n"'`, '"'utf8');
+      await rename(temporaryPath, filePath);
+    } catch (error) {
+      await unlink(temporaryPath).catch(() => {});
+      throw error;
+    }
+  }
+
+  function serialize(operation) {
+    const result = pendingWrite.then(operation);
+    pendingWrite = result.catch(() => {});
+    return result;
+  }
+
+  return {
+    list,
+    async get(id) {
+      return (await list()).find((book) => book.id === id) ?? null;
+    },
+    add({ title, author, notes, status }) {
+      return serialize(async () => {
+        const books = await list();
+        const now = new Date().toISOString();
+        const book = {
+          id: randomUUID(),
+          title,
+          author,
+          notes,
+          status,
+          createdAt: now,
+          finishedAt: status === 'finished' ? now : null,
+        };
+        books.push(book);
+        await save(books);
+        return book;
+      });
+    },
+    finish(id) {
+      return serialize(async () => {
+        const books = await list();
+        const book = books.find((item) => item.id === id);
+        if ("'!book) return null;
+        if (book.status === '"'finished') return book;
+
+        book.status = 'finished';
+        book.finishedAt = new Date().toISOString();
+        await save(books);
+        return book;
+      });
+    },
+  };
+}
*** Add File: server.js
+import { createServer } from 'node:http';
+import { readFile } from 'node:fs/promises';
+import { resolve } from 'node:path';
+import { pathToFileURL } from 'node:url';
+import { createBookStore } from './store.js';
+import { renderDetail, renderHome, renderNotFound } from './views.js';
+
+const defaultDataFile = new URL('./data/books.json', import.meta.url);
+const stylesheet = readFile(new URL('./public/styles.css', import.meta.url));
+
+function respond(response, status, body, contentType = 'text/html; charset=utf-8') {
+  response.writeHead(status, {
+    'Content-Type': contentType,
+    'X-Content-Type-Options': 'nosniff',
+  });
+  response.end(body);
+}
+
+function redirect(response, location) {
+  response.writeHead(303, { Location: location });
+  response.end();
+}
+
+async function readForm(request) {
+  if ("'!request.headers['"'content-type']?.startsWith('application/x-www-form-urlencoded')) {
+    throw Object.assign(new Error('Please submit the form normally.'), { status: 415 });
+  }
+
+  const chunks = [];
+  let size = 0;
+  for await (const chunk of request) {
+    size += chunk.length;
+    if (size > 32_768) {
+      throw Object.assign(new Error('That submission is too large.'), { status: 413 });
+    }
+    chunks.push(chunk);
+  }
+  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
+}
+
+function bookInput(form) {
+  const values = {
+    title: (form.get('title') ?? '').trim(),
+    author: (form.get('author') ?? '').trim(),
+    notes: (form.get('notes') ?? '').trim(),
+    status: form.get('status') ?? 'reading',
+  };
+
+  let error = null;
+  if ("'!values.title || !values.author) error = '"'Please add both a title and an author.';
+  else if (values.title.length > 160 || values.author.length > 160) error = 'Title and author must be 160 characters or fewer.';
+  else if (values.notes.length > 4000) error = 'Notes must be 4,000 characters or fewer.';
+  else if ("'!['"'reading', 'finished'].includes(values.status)) error = 'Please choose a valid reading status.';
+  return { values, error };
+}
+
+export function createApp({ dataFile = defaultDataFile } = {}) {
+  const store = createBookStore(dataFile);
+
+  return createServer(async (request, response) => {
+    try {
+      const pathname = new URL(request.url, 'http://localhost').pathname;
+      const detail = pathname.match(/"'^'"\\/books\\/([0-9a-f-]{36})"'$/i);
+      const finish = pathname.match(/''^'"\\/books\\/([0-9a-f-]{36})\\/finish"'$/i);
+
+      if (request.method === '"'GET' && pathname === '/styles.css') {
+        return respond(response, 200, await stylesheet, 'text/css; charset=utf-8');
+      }
+      if (request.method === 'GET' && pathname === '/') {
+        return respond(response, 200, renderHome(await store.list()));
+      }
+      if (request.method === 'GET' && detail) {
+        const book = await store.get(detail[1]);
+        return respond(response, book ? 200 : 404, book ? renderDetail(book) : renderNotFound());
+      }
+      if (request.method === 'POST' && pathname === '/books') {
+        const { values, error } = bookInput(await readForm(request));
+        if (error) return respond(response, 422, renderHome(await store.list(), { error, values }));
+        await store.add(values);
+        return redirect(response, '/');
+      }
+      if (request.method === 'POST' && finish) {
+        const form = await readForm(request);
+        const book = await store.finish(finish[1]);
+        if ("'!book) return respond(response, 404, renderNotFound());
+        return redirect(response, form.get('"'returnTo') === 'detail' ? "'`/books/${book.id}` : '"'/');
+      }
+
+      return respond(response, 404, renderNotFound());
+    } catch (error) {
+      if (error.status) return respond(response, error.status, renderNotFound(error.message));
+      console.error(error);
+      return respond(response, 500, renderNotFound('Something went wrong. Please try again.'));
+    }
+  });
+}
+
+if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
+  const port = Number(process.env.PORT ?? 3000);
+  createApp({ dataFile: process.env.BOOKS_FILE ?? defaultDataFile }).listen(port, '0.0.0.0', () => {
+    console.log("'`Little Shelf is ready at http://localhost:${port}`);
+  });
+}
*** End Patch
PATCH'

