*** Begin Patch
*** Add File: server.test.js
+import { afterEach, beforeEach, describe, expect, it } from 'vitest';
+import { mkdtemp, readFile, rm } from 'node:fs/promises';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { createApp } from './server.js';
+
+describe('Little Shelf', () => {
+  let directory;
+  let dataFile;
+  let server;
+  let baseUrl;
+
+  async function start() {
+    server = createApp({ dataFile });
+    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
+    baseUrl = "'`http://127.0.0.1:${server.address().port}`;
+  }
+
+  async function stop() {
+    if (server) await new Promise((resolve) => server.close(resolve));
+    server = null;
+  }
+
+  async function submit(path, fields) {
+    return fetch(`${baseUrl}${path}`, {
+      method: '"'POST',
+      body: new URLSearchParams(fields),
+      redirect: 'manual',
+    });
+  }
+
+  beforeEach(async () => {
+    directory = await mkdtemp(join(tmpdir(), 'little-shelf-'));
+    dataFile = join(directory, 'books.json');
+    await start();
+  });
+
+  afterEach(async () => {
+    await stop();
+    await rm(directory, { recursive: true, force: true });
+  });
+
+  it('shows an empty shelf and serves the styles', async () => {
+    const home = await fetch(baseUrl);
+    expect(home.status).toBe(200);
+    expect(await home.text()).toContain('A fresh chapter starts here');
+    const styles = await fetch("'`${baseUrl}/styles.css`);
+    expect(styles.status).toBe(200);
+    expect(styles.headers.get('"'content-type')).toContain('text/css');
+  });
+
+  it('adds a book, gives it a shareable detail page, and keeps it after restart', async () => {
+    const response = await submit('/books', {
+      title: 'The Left Hand of Darkness',
+      author: 'Ursula K. Le Guin',
+      notes: 'A thought worth keeping.\\nAnother thought.',
+      status: 'reading',
+    });
+    expect(response.status).toBe(303);
+    expect(response.headers.get('location')).toBe('/');
+
+    const [book] = JSON.parse(await readFile(dataFile, 'utf8'));
+    expect(book.title).toBe('The Left Hand of Darkness');
+    const home = await (await fetch(baseUrl)).text();
+    expect(home).toContain('The Left Hand of Darkness');
+    const detail = await fetch("'`${baseUrl}/books/${book.id}`);
+    expect(detail.status).toBe(200);
+    const page = await detail.text();
+    expect(page).toContain('"'Ursula K. Le Guin');
+    expect(page).toContain('A thought worth keeping.\\nAnother thought.');
+
+    await stop();
+    await start();
+    expect(await (await fetch("'`${baseUrl}/books/${book.id}`)).text()).toContain('"'The Left Hand of Darkness');
+  });
+
+  it('moves books to finished and preserves that status', async () => {
+    await submit('/books', { title: 'Piranesi', author: 'Susanna Clarke', status: 'reading' });
+    const [book] = JSON.parse(await readFile(dataFile, 'utf8'));
+    const response = await submit("'`/books/${book.id}/finish`, { returnTo: '"'detail' });
+    expect(response.status).toBe(303);
+    expect(response.headers.get('location')).toBe("'`/books/${book.id}`);
+    const updated = JSON.parse(await readFile(dataFile, '"'utf8'))[0];
+    expect(updated.status).toBe('finished');
+    expect(updated.finishedAt).toBeTruthy();
+    expect(await (await fetch("'`${baseUrl}/books/${book.id}`)).text()).toContain('"'Finished on');
+    expect(await (await fetch(baseUrl)).text()).toContain('Finished books <span class=\"count\">1</span>');
+  });
+
+  it('validates input and escapes displayed book content', async () => {
+    const invalid = await submit('/books', { title: 'No author', author: ' ', status: 'reading' });
+    expect(invalid.status).toBe(422);
+    expect(await invalid.text()).toContain('Please add both a title and an author.');
+
+    await submit('/books', { title: '<script>alert(1)</script>', author: 'A & B', notes: '<img src=x>', status: 'finished' });
+    const [book] = JSON.parse(await readFile(dataFile, 'utf8'));
+    const detail = await (await fetch("'`${baseUrl}/books/${book.id}`)).text();
+    expect(detail).toContain('"'&lt;script&gt;alert(1)&lt;/script&gt;');
+    expect(detail).toContain('A &amp; B');
+    expect(detail).toContain('&lt;img src=x&gt;');
+    expect(detail).not.toContain('<script>alert(1)</script>');
+  });
+
+  it('does not lose books when submissions arrive together', async () => {
+    await Promise.all(Array.from({ length: 8 }, (_, index) => submit('/books', {
+      title: "'`Book ${index}`,
+      author: '"'Reader',
+      status: 'reading',
+    })));
+    expect(JSON.parse(await readFile(dataFile, 'utf8'))).toHaveLength(8);
+  });
+});
*** Add File: README.md
+# Little Shelf
+
+A small, account-free reading tracker. Add books with notes, see what you're reading and what you've finished, and share a book's detail-page URL.
+
+## Run locally
+
+Requires Node.js 20 or newer.
+
+"'```sh
+npm install
+npm start
+```
+
+Open `http://localhost:3000`. Use `npm run dev` to restart automatically while editing, `npm test` to run tests, or set `PORT` to use another port.
+
+Books are saved to `data/books.json` as soon as you add or finish one. The file is kept between restarts and ignored by Git. Set `BOOKS_FILE` to use a different file path. Back up that JSON file to keep your books when moving the app.
*** End Patch
PATCH
npm test && npm run build && git status --short'

