+import { randomUUID } from 'node:crypto';
+import { mkdir, readFile, rename, unlink, writeFile } from 'node:fs/promises';
+import { dirname } from 'node:path';
+
+export function createBookStore(filePath) {
+  let pendingWrite = Promise.resolve();
+
+  async function list() {
+    try {
+      return JSON.parse(await readFile(filePath, 'utf8'));
+    } catch (error) {
+      if (error.code === 'ENOENT') return [];
+      throw error;
+    }
+  }
+
+  async function save(books) {
+    await mkdir(dirname(filePath), { recursive: true });
+    const temporaryPath = "'`${filePath}.${randomUUID()}.tmp`;
+
+    try {
+      await writeFile(temporaryPath, `${JSON.stringify(books, null, 2)}'"\\n"'`, '"'utf8');
+      await rename(temporaryPath, filePath);
+    } catch (error) {
+      await unlink(temporaryPath).catch(() => {});
+      throw error;
+    }
+  }
+
+  function serialize(operation) {
+    const result = pendingWrite.then(operation);
+    pendingWrite = result.catch(() => {});
+    return result;
+  }
+
+  return {
+    list,
+    async get(id) {
+      return (await list()).find((book) => book.id === id) ?? null;
+    },
+    add({ title, author, notes, status }) {
+      return serialize(async () => {
+        const books = await list();
+        const now = new Date().toISOString();
+        const book = {
+          id: randomUUID(),
+          title,
+          author,
+          notes,
+          status,
+          createdAt: now,
+          finishedAt: status === 'finished' ? now : null,
+        };
+        books.push(book);
+        await save(books);
+        return book;
+      });
+    },
+    finish(id) {
+      return serialize(async () => {
+        const books = await list();
+        const book = books.find((item) => item.id === id);
+        if ("'!book) return null;
+        if (book.status === '"'finished') return book;
+
+        book.status = 'finished';
+        book.finishedAt = new Date().toISOString();
+        await save(books);
+        return book;
+      });
+    },
+  };
+}
